const template = $('Code: Generate Template (HTML + CSS)1').first().json.html;
function getStoredData() {
  try { return $('Code: Handle Image Choice1').first().json; } catch (e) {}
  try { return $('Code: Handle Text Image Choice1').first().json; } catch (e) {}
  throw new Error('Could not find business/plan/seo data from either image-choice handler node.');
}
const stored = getStoredData();
const business = stored.business;
const seo = stored.seo;
const plan = stored.plan;
const content = $('Code: Parse Content JSON1').first().json;

const seoTitle = seo.title || business.name;
const metaDescription = seo.metaDescription || '';
const keywords = Array.isArray(seo.keywords) ? seo.keywords.join(', ') : (seo.keywords || '');
const ogTitle = seo.ogTitle || seoTitle;
const ogDescription = seo.ogDescription || metaDescription;
const canonicalUrl = seo.canonicalUrl || 'https://example.com/';
const twitterCard = seo.twitterCard || 'summary_large_image';
const jsonLdSchema = typeof seo.jsonLdSchema === 'string'
  ? seo.jsonLdSchema
  : JSON.stringify(seo.jsonLdSchema || {});

const seoHead = `
<title>${seoTitle}</title>
<meta name="title" content="${seoTitle}">
<meta name="description" content="${metaDescription}">
<meta name="keywords" content="${keywords}">
<meta name="robots" content="index, follow">
<meta name="author" content="Karthikeyan">

<meta property="og:title" content="${ogTitle}">
<meta property="og:description" content="${ogDescription}">
<meta property="og:url" content="${canonicalUrl}">
<meta property="og:type" content="website">
<meta property="og:locale" content="en_US">

<meta name="twitter:card" content="${twitterCard}">
<meta name="twitter:title" content="${ogTitle}">
<meta name="twitter:description" content="${ogDescription}">

<meta name="googlebot" content="index, follow">
<meta name="bingbot" content="index, follow">

<link rel="canonical" href="${canonicalUrl}">

<script type="application/ld+json">${jsonLdSchema}</script>
`;

const servicesHtml = content.services.length
  ? content.services.map(s => `<div class="service-card"><h3>${s.title}</h3><p>${s.description}</p></div>`).join('\n')
  : '';

const whyChooseHtml = content.whyChooseUs.length
  ? content.whyChooseUs.map(w => `<div class="why-item">✔ ${w}</div>`).join('\n')
  : '';

const phoneDigits = business.phone.replace(/\D/g, '');
const fontUrlName = (plan.font || 'Poppins').replace(/\s+/g, '+');

let html = template
  .replaceAll('{{seo_head}}', seoHead)
  .replaceAll('{{font_url}}', fontUrlName)
  .replaceAll('{{company_name}}', business.name)
  .replaceAll('{{phone}}', business.phone)
  .replaceAll('{{address}}', business.address)
  .replaceAll('{{hero_heading}}', content.heroHeading)
  .replaceAll('{{hero_subheading}}', content.heroSubheading)
  .replaceAll('{{about_us}}', content.aboutUs)
  .replaceAll('{{call_link}}', `tel:+91${phoneDigits}`)
  .replaceAll('{{services_block}}', servicesHtml)
  .replaceAll('{{why_choose_block}}', whyChooseHtml);

return [{ json: { html } }];

