function getStoredData() {
  try { return $('Code: Handle Image Choice1').first().json; } catch (e) {}
  try { return $('Code: Handle Text Image Choice1').first().json; } catch (e) {}
  throw new Error('Could not find business/plan/seo data from either image-choice handler node.');
}
const business = getStoredData().business;
const folderName = business.name.replace(/\s+/g, '_').toLowerCase();

const html = $('Code: Fill index.html1').first().json.html;
const css = $('Code: Fill style.css1').first().json.css;
const seoFiles = $('Code: Generate SEO Files1').first().json;

// Properly read the banner image bytes via n8n's binary data helper.
// Reading binary.data.data directly (the old approach) can silently return
// an internal storage reference instead of the real image bytes when n8n
// isn't holding binaries in plain memory (e.g. filesystem/S3 binary mode),
// which is what was producing a 0 KB banner.png in the zip.
// This node's own input item now carries the image binary because the
// "Merge" node upstream combines the SEO-files branch with the
// "Generate an image" branch by position before reaching this node.
const bannerBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');



if (!bannerBuffer || bannerBuffer.length === 0) {
  throw new Error('Banner image buffer is empty. Check that the "Merge" node before this step is set to Combine > Combine by Position, and that "Generate an image" is actually returning binary data named "data".');
}

const bannerBinaryData = await this.helpers.prepareBinaryData(bannerBuffer, 'banner.png', 'image/png');

return [{
  json: { folderName },
  binary: {
    html: {
      data: Buffer.from(html).toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    },
    css: {
      data: Buffer.from(css).toString('base64'),
      mimeType: 'text/css',
      fileName: 'style.css'
    },
    robots: {
      data: Buffer.from(seoFiles.robots).toString('base64'),
      mimeType: 'text/plain',
      fileName: 'robots.txt'
    },
    sitemap: {
      data: Buffer.from(seoFiles.sitemap).toString('base64'),
      mimeType: 'application/xml',
      fileName: 'sitemap.xml'
    },
    manifest: {
      data: Buffer.from(seoFiles.manifest).toString('base64'),
      mimeType: 'application/json',
      fileName: 'manifest.json'
    },
    banner: bannerBinaryData
  }
}];

