}

// HARD mandatory-field check - business name, type, address, phone are always required
const b = parsed.business;
const required = { name: b.name, type: b.type, address: b.address, phone: b.phone };
const missing = [];
for (const [field, value] of Object.entries(required)) {
  if (!value || String(value).trim() === '' || String(value).toLowerCase().includes('not found') || String(value).toLowerCase().includes('unknown')) {
    missing.push(field);
  }
}
parsed.missingFields = missing;

return [{ json: parsed }];

