const chatId = $('Telegram Trigger').first().json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingSites) staticData.pendingSites = {};
staticData.pendingSites[chatId] = $json;

return [{ json: { chatId } }];

const chatId = $json.callback_query.message.chat.id;
const wantsImage = $json.callback_query.data === 'with_image';

const staticData = $getWorkflowStaticData('global');
const stored = (staticData.pendingSites || {})[chatId];

if (!stored) {
  throw new Error('No pending site request found for this chat. Please send your business details again to start over.');
}

delete staticData.pendingSites[chatId];

return [{ json: { ...stored, wantsImage } }];

// Fallback banner used when the business owner picks "Without Image".
// Embedded as base64 so it never depends on an external URL or API call.
const DEFAULT_BANNER_BASE64 = "";

const bannerBuffer = Buffer.from(DEFAULT_BANNER_BASE64, 'base64');
const bannerBinaryData = await this.helpers.prepareBinaryData(bannerBuffer, 'banner.png', 'image/png');

return [{ json: $json, binary: { data: bannerBinaryData } }];

const chatId = String($json.message.chat.id);
const text = ($json.message.text || '').trim().toLowerCase();
const wantsImage = text === 'with image';

const staticData = $getWorkflowStaticData('global');
const stored = (staticData.pendingSites || {})[chatId];

if (!stored) {
  throw new Error('No pending site request found for this chat. Please send your business details again to start over.');
}

delete staticData.pendingSites[chatId];

return [{ json: { ...stored, wantsImage } }];

// wantsImage may have been set by either the button-tap handler or the
// typed-reply handler -- only one of them runs per execution, so look up
// whichever one actually ran instead of assuming a fixed node name.
let wantsImage;
try {
  wantsImage = $('Code: Handle Image Choice1').first().json.wantsImage;
} catch (e) {
  try {
    wantsImage = $('Code: Handle Text Image Choice1').first().json.wantsImage;
  } catch (e2) {
    wantsImage = true; // safe default if neither ran for some reason
  }
}

return [{ json: { ...$json, wantsImage } }];
